document.querySelector('#start').onclick=startGame;document.querySelector('#again').onclick=startGame;
function worldMouse(){let s=game?game.cam.scale:1;return{x:(mouse.x-vw/2)/s+game.cam.x+vw/(2*s),y:(mouse.y-vh/2)/s+game.cam.y+vh/(2*s)}}
canvas.addEventListener('pointermove',e=>{mouse.x=e.clientX;mouse.y=e.clientY});canvas.addEventListener('pointerdown',e=>{if(e.button===0){mouse.down=true;canvas.setPointerCapture?.(e.pointerId)}});addEventListener('pointerup',e=>{if(e.button===0)mouse.down=false});
addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.key==='Escape'&&game&&!game.over)togglePause();if(e.key.toLowerCase()==='r'&&game)reload();if(e.key.toLowerCase()==='q'&&game)useMed()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
const joyEl=document.querySelector('#joy');function joyMove(e){let r=joyEl.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.min(42,Math.hypot(dx,dy));if(Math.hypot(dx,dy)>0){joy.x=dx/Math.hypot(dx,dy)*m/42;joy.y=dy/Math.hypot(dx,dy)*m/42}joyEl.style.setProperty('--jx',`${joy.x*38}px`);joyEl.style.setProperty('--jy',`${joy.y*38}px`);joyEl.style.backgroundPosition='center'}
joyEl.addEventListener('pointerdown',e=>{joyEl.setPointerCapture(e.pointerId);joyMove(e)});joyEl.addEventListener('pointermove',e=>{if(e.buttons)joyMove(e)});for(let ev of ['pointerup','pointercancel'])joyEl.addEventListener(ev,()=>{joy.x=joy.y=0;joyEl.style.setProperty('--jx','0px');joyEl.style.setProperty('--jy','0px')});document.querySelector('#fireBtn').addEventListener('pointerdown',e=>{touchFire=true;e.currentTarget.setPointerCapture(e.pointerId)});document.querySelector('#fireBtn').addEventListener('pointerup',()=>touchFire=false);document.querySelector('#fireBtn').addEventListener('pointercancel',()=>touchFire=false);document.querySelector('#reloadBtn').onclick=reload;
document.querySelector('#resume').onclick=()=>togglePause(false);document.querySelector('#quit').onclick=()=>{game=null;paused=false;ui.pause.classList.add('hidden');ui.hud.classList.remove('active');ui.menu.classList.remove('hidden');document.querySelector('#mobile').style.display='none'};
function togglePause(value=!paused){paused=value;ui.pause.classList.toggle('hidden',!paused);if(!paused){last=performance.now();requestAnimationFrame(loop)}}
function reload(){if(!game||paused)return;let p=game.player;if(p.reload||p.ammo===24||p.reserve<=0)return;p.reload=1.15;toast('RELOADING')}
function useMed(){if(!game||paused)return;let p=game.player;if(p.medkits>0&&p.hp<100){p.medkits--;p.hp=Math.min(100,p.hp+42);toast('MEDKIT USED +42')}}
function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>ui.toast.classList.remove('show'),1250)}
function shoot(owner,target,spread=0){let a=angle(owner,target)+rand(-spread,spread);game.bullets.push({x:owner.x+Math.cos(a)*18,y:owner.y+Math.sin(a)*18,vx:Math.cos(a)*690,vy:Math.sin(a)*690,life:.85,owner,damage:owner===game.player?34:12});owner.angle=a;if(owner===game.player){owner.ammo--;owner.fireCd=.15;for(let i=0;i<4;i++)game.particles.push({x:owner.x+Math.cos(a)*20,y:owner.y+Math.sin(a)*20,vx:Math.cos(a)*rand(80,240)+rand(-80,80),vy:Math.sin(a)*rand(80,240)+rand(-80,80),life:rand(.08,.2),color:'#ffe68a',size:rand(2,4)})}}
function playerDamage(n){let p=game.player;if(p.invuln>0)return;p.hp-=n;p.invuln=.18;shake=5;ui.flash.classList.add('on');setTimeout(()=>ui.flash.classList.remove('on'),90);if(p.hp<=0)endGame(false)}
function endGame(win){if(!game||game.over)return;game.over=true;ui.result.classList.remove('hidden');document.querySelector('#resultEyebrow').textContent=win?'ISLAND CHAMPION':'MATCH COMPLETE';document.querySelector('#resultTitle').textContent=win?'VICTORY':'ELIMINATED';document.querySelector('#resultText').textContent=win?`You outlasted everyone with ${game.kills} elimination${game.kills===1?'':'s'}. Ashwood is yours.`:`You placed #${Math.max(2,game.bots.filter(b=>!b.dead).length+2)} with ${game.kills} elimination${game.kills===1?'':'s'}. Drop back in and try again.`)}
function update(dt){let g=game,p=g.player;g.time+=dt;p.invuln=Math.max(0,p.invuln-dt);p.fireCd=Math.max(0,p.fireCd-dt);if(p.reload>0){p.reload-=dt;if(p.reload<=0){let n=Math.min(24-p.ammo,p.reserve);p.ammo+=n;p.reserve-=n;toast('RELOADED')}}
let ix=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,iy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y,m=Math.hypot(ix,iy);if(m>1){ix/=m;iy/=m}let nx=p.x+ix*p.speed*dt,ny=p.y+iy*p.speed*dt;if(!collides(nx,p.y,p.r)){p.x=clamp(nx,20,W-20)}if(!collides(p.x,ny,p.r)){p.y=clamp(ny,20,H-20)}
let wm=worldMouse();if(mouse.x||mouse.y)p.angle=angle(p,wm);else if(g.bots.length){let b=nearestAlive(p);if(b)p.angle=angle(p,b)}
if((mouse.down||touchFire)&&p.fireCd<=0&&p.reload<=0){if(p.ammo>0){let target=mouse.down?wm:nearestAlive(p);shoot(p,target||{x:p.x+Math.cos(p.angle)*100,y:p.y+Math.sin(p.angle)*100})}else reload()}
let elapsed=Math.max(0,g.time-g.zone.delay);g.zone.r=g.zone.start-(g.zone.start-g.zone.target)*clamp(elapsed/g.zone.duration,0,1);if(g.time>g.zone.delay&&dist(p,g.zone)>g.zone.r){playerDamage(8*dt);if(Math.floor(g.time*2)%4===0)toast('OUTSIDE SAFE ZONE')}
for(let b of g.bots){if(b.dead)continue;b.think-=dt;b.fire-=dt;let target=p;if(b.think<=0){b.think=rand(.3,.8);b.wander=rand(0,TAU);let d=dist(b,p);if(d>520||Math.random()<.2)target=null}let d=dist(b,p);if(d<470){b.angle=angle(b,p);let dir=d>220?1:d<155?-.55:0;let tx=b.x+Math.cos(b.angle)*b.speed*dir*dt,ty=b.y+Math.sin(b.angle)*b.speed*dir*dt;if(!collides(tx,b.y,b.r))b.x=tx;if(!collides(b.x,ty,b.r))b.y=ty;if(d<400&&b.fire<=0){shoot(b,p,.09);b.fire=rand(.75,1.35)}}else{let tx=b.x+Math.cos(b.wander)*b.speed*.55*dt,ty=b.y+Math.sin(b.wander)*b.speed*.55*dt;if(!collides(tx,b.y,b.r))b.x=tx;if(!collides(b.x,ty,b.r))b.y=ty}
if(g.time>g.zone.delay&&dist(b,g.zone)>g.zone.r){b.hp-=7*dt;if(b.hp<=0)killBot(b,null)} }
for(let bullet of g.bullets){bullet.x+=bullet.vx*dt;bullet.y+=bullet.vy*dt;bullet.life-=dt;if(collides(bullet.x,bullet.y,2)){bullet.life=0;continue}if(bullet.owner===p){for(let b of g.bots){if(!b.dead&&Math.hypot(b.x-bullet.x,b.y-bullet.y)<b.r+4){b.hp-=bullet.damage;bullet.life=0;for(let i=0;i<5;i++)g.particles.push({x:bullet.x,y:bullet.y,vx:rand(-90,90),vy:rand(-90,90),life:.28,color:'#ffb169',size:rand(2,5)});if(b.hp<=0)killBot(b,p);break}}}else if(Math.hypot(p.x-bullet.x,p.y-bullet.y)<p.r+4){playerDamage(bullet.damage);bullet.life=0}}
g.bullets=g.bullets.filter(b=>b.life>0);for(let l of g.loot)if(!l.taken&&dist(p,l)<34){l.taken=true;if(l.type==='med'){p.medkits++;toast('MEDKIT PICKED UP')}else{p.reserve+=36;toast('AMMO +36')}}for(let part of g.particles){part.x+=part.vx*dt;part.y+=part.vy*dt;part.life-=dt}g.particles=g.particles.filter(a=>a.life>0);
g.cam.scale=clamp(Math.min(vw/900,vh/620),.48,1);let visW=vw/g.cam.scale,visH=vh/g.cam.scale;g.cam.x=clamp(p.x-visW/2,0,W-visW);g.cam.y=clamp(p.y-visH/2,0,H-visH);updateHud()}
function nearestAlive(from){let alive=game.bots.filter(b=>!b.dead);if(!alive.length)return null;return alive.reduce((a,b)=>dist(a,from)<dist(b,from)?a:b)}
function collides(x,y,r){return buildings.some(b=>x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)}
function killBot(b,killer){b.dead=true;if(killer===game.player){game.kills++;game.loot.push({x:b.x,y:b.y,type:Math.random()<.35?'med':'ammo',taken:false});toast('ELIMINATION +1');if(game.bots.every(x=>x.dead))endGame(true)}else if(game.bots.every(x=>x.dead))endGame(true)}
function updateHud(){let alive=game.bots.filter(b=>!b.dead).length+1;ui.alive.textContent=alive;ui.kills.textContent=game.kills;ui.health.textContent=Math.max(0,Math.ceil(game.player.hp));ui.bar.style.width=`${clamp(game.player.hp,0,100)}%`;ui.bar.style.background=game.player.hp<30?'#ff6657':'var(--lime)';ui.ammo.textContent=game.player.ammo;ui.reserve.textContent=game.player.reserve;let left=Math.max(0,game.zone.delay-game.time);ui.timer.textContent=left>0?`${String(Math.floor(left/60)).padStart(2,'0')}:${String(Math.floor(left%60)).padStart(2,'0')}`:'CLOSING';}

